// SPEC-WEB §3.3: strings are generated by tools/export_web_strings.py (monorepo) into fi/sv/en.json.
import en from './en.json';
import fi from './fi.json';
import sv from './sv.json';

export type Lang = 'fi' | 'sv' | 'en';
export const LANGS: Lang[] = ['fi', 'sv', 'en'];
export const CATALOGS: Record<Lang, Record<string, string>> = { fi, sv, en };

let current: Lang = 'fi';
export const getLang = (): Lang => current;
export const setLang = (l: Lang): void => {
  current = l;
};

export function detectLang(preferred: readonly string[]): Lang {
  for (const p of preferred) {
    const code = p.slice(0, 2).toLowerCase();
    if (code === 'fi' || code === 'sv') return code;
    if (code === 'en') return 'en';
  }
  return 'en';
}

export const has = (key: string): boolean => key in CATALOGS[current];

export function t(key: string, params?: Record<string, string | number>): string {
  const raw = CATALOGS[current][key] ?? CATALOGS.en[key] ?? key;
  return params ? raw.replace(/\{(\w+)\}/g, (_m, k: string) => String(params[k] ?? `{${k}}`)) : raw;
}
